using System.Linq;
using Autodesk.Revit.DB;
using Autodesk.Revit.DB.Structure;

var doc = Document;
// setup: a structural column symbol; base = lowest level, top = highest level
var symbol = new FilteredElementCollector(doc).OfCategory(BuiltInCategory.OST_StructuralColumns).OfClass(typeof(FamilySymbol)).Cast<FamilySymbol>().First();
var levels = new FilteredElementCollector(doc).OfClass(typeof(Level)).Cast<Level>().OrderBy(l => l.Elevation).ToList();
var baseLevel = levels.First();
var topLevel  = levels.Last();
var loc = new XYZ(30, 0, 0);

ElementId colId = null;
// step 1: activate the symbol; place a vertical column at the point, then set its top level
Connector.WithTransaction(doc, () => {
    if (!symbol.IsActive) symbol.Activate();
    var col = doc.Create.NewFamilyInstance(loc, symbol, baseLevel, StructuralType.Column);
    var topParam = col.get_Parameter(BuiltInParameter.FAMILY_TOP_LEVEL_PARAM);
    if (topParam != null && topLevel.Id != baseLevel.Id) topParam.Set(topLevel.Id);
    colId = col.Id;
});

var created = (FamilyInstance)doc.GetElement(colId);
var topLevelName = created.get_Parameter(BuiltInParameter.FAMILY_TOP_LEVEL_PARAM) is Parameter p && p.AsElementId() != ElementId.InvalidElementId
    ? (doc.GetElement(p.AsElementId()) as Level)?.Name : null;
return new { colId = colId.ToString(), symbol = symbol.Name, baseLevel = baseLevel.Name, topLevel = topLevelName, structuralType = created.StructuralType.ToString(), category = created.Category?.Name };
